(() => {
  'use strict';
  const KEY = 'brahmafarm.workspace.v1';
  const ACTIVITIES = ['Planting','Irrigation','Health','Harvest','Expense','Sale','Observation'];
  const HEALTH = ['','Good','Watch','Poor'];
  const UNITS = ['','kg','bags','plants','acres','hours','L'];
  const SAMPLE = [
    {date:'2026-06-04',field:'North Field',crop:'Tomato',activity:'Planting',quantity:0.8,unit:'acres',water:null,cost:14800,revenue:null,health:'',notes:'Sample: transplanting and bed preparation'},
    {date:'2026-06-18',field:'North Field',crop:'Tomato',activity:'Irrigation',quantity:null,unit:'',water:8200,cost:1200,revenue:null,health:'Good',notes:'Sample: drip irrigation'},
    {date:'2026-07-09',field:'East Field',crop:'Okra',activity:'Planting',quantity:0.6,unit:'acres',water:null,cost:9700,revenue:null,health:'',notes:'Sample: sowing'},
    {date:'2026-07-22',field:'North Field',crop:'Tomato',activity:'Health',quantity:null,unit:'',water:null,cost:2100,revenue:null,health:'Watch',notes:'Sample: leaf spotting observed; inspect before treatment'},
    {date:'2026-08-14',field:'East Field',crop:'Okra',activity:'Irrigation',quantity:null,unit:'',water:5400,cost:900,revenue:null,health:'Good',notes:'Sample: irrigation run'},
    {date:'2026-08-28',field:'North Field',crop:'Tomato',activity:'Sale',quantity:1250,unit:'kg',water:null,cost:3400,revenue:41200,health:'Good',notes:'Sample: market sale'},
    {date:'2026-09-12',field:'East Field',crop:'Okra',activity:'Sale',quantity:670,unit:'kg',water:null,cost:1600,revenue:26800,health:'Good',notes:'Sample: market sale'},
    {date:'2026-09-21',field:'North Field',crop:'Tomato',activity:'Irrigation',quantity:null,unit:'',water:9100,cost:1450,revenue:null,health:'Good',notes:'Sample: irrigation run'},
    {date:'2026-10-06',field:'South Field',crop:'Wheat',activity:'Planting',quantity:1.2,unit:'acres',water:null,cost:16300,revenue:null,health:'',notes:'Sample: field preparation and seed'},
    {date:'2026-10-18',field:'East Field',crop:'Okra',activity:'Harvest',quantity:520,unit:'kg',water:null,cost:1100,revenue:null,health:'Watch',notes:'Sample: inspect leaf curl in one section'},
    {date:'2026-11-03',field:'East Field',crop:'Okra',activity:'Sale',quantity:520,unit:'kg',water:null,cost:950,revenue:18400,health:'Good',notes:'Sample: second market sale'},
    {date:'2026-11-08',field:'South Field',crop:'Wheat',activity:'Irrigation',quantity:null,unit:'',water:7800,cost:1150,revenue:null,health:'Good',notes:'Sample: first irrigation'}
  ];
  const $ = s => document.querySelector(s);
  const $$ = s => [...document.querySelectorAll(s)];
  const esc = s => String(s ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const uid = () => (globalThis.crypto?.randomUUID?.() || `${Date.now()}-${Math.random().toString(36).slice(2)}`);
  const number = value => value === '' || value == null || !Number.isFinite(Number(value)) ? null : Number(value);
  const fmtNum = (v,max=0) => new Intl.NumberFormat('en-IN',{maximumFractionDigits:max}).format(v ?? 0);
  const money = v => `₹${fmtNum(Math.abs(v))}`;
  const signedMoney = v => `${v < 0 ? '−' : ''}${money(v)}`;
  const shortMoney = v => Math.abs(v)>=100000 ? `₹${(Math.abs(v)/100000).toFixed(1)}L` : Math.abs(v)>=1000 ? `₹${(Math.abs(v)/1000).toFixed(1)}k` : money(v);
  const prettyDate = d => { const x=new Date(`${d}T12:00:00`); return Number.isNaN(x.getTime()) ? d : x.toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'}); };
  const monthName = m => new Date(2026,Number(m)-1,1).toLocaleDateString('en-IN',{month:'short'});
  const monthKey = d => /^\d{4}-\d{2}/.test(d||'') ? d.slice(0,7) : '';
  const titleCase = s => s.trim().replace(/\s+/g,' ');
  const val = (r,k) => typeof r[k]==='number' ? r[k] : 0;
  let workspace;
  let editId = null;
  let toastTimer;
  let confirmCallback = null;

  function sampleWorkspace(){return {version:1,sample:true,fields:[{name:'North Field',area:0.8},{name:'East Field',area:0.6},{name:'South Field',area:1.2}],records:SAMPLE.map(r=>({...r,id:uid()}))};}
  function load(){try{const raw=localStorage.getItem(KEY);if(raw){const x=JSON.parse(raw);if(Array.isArray(x.records)&&Array.isArray(x.fields))return x;}}catch(e){console.warn('Could not read stored workspace',e);}return sampleWorkspace();}
  function save(){localStorage.setItem(KEY,JSON.stringify(workspace));}
  function notify(message){const el=$('#toast');el.textContent=message;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),3200);}
  function showView(name){$$('.view').forEach(v=>v.classList.toggle('active',v.id===`view-${name}`));$$('.nav-item').forEach(v=>v.classList.toggle('active',v.dataset.view===name));const names={overview:'Overview',sheet:'BrahmaSpreadsheet',insights:'Insights',research:'Research helper',settings:'Farm settings'};$('#breadcrumbCurrent').textContent=names[name];history.replaceState(null,'',`#${name}`);window.scrollTo({top:0,behavior:'smooth'});render();}
  function totals(records=workspace.records){return records.reduce((a,r)=>{a.revenue+=val(r,'revenue');a.cost+=val(r,'cost');a.water+=val(r,'water');if(r.activity==='Harvest'&&r.unit==='kg')a.harvest+=val(r,'quantity');if(r.health)a.health.push(r);return a;},{revenue:0,cost:0,water:0,harvest:0,health:[]});}
  function cropStats(){const out={};for(const r of workspace.records){const c=r.crop||'Unassigned';if(!out[c])out[c]={name:c,revenue:0,cost:0,water:0,harvest:0,rows:0,sales:0,health:[]};const x=out[c];x.revenue+=val(r,'revenue');x.cost+=val(r,'cost');x.water+=val(r,'water');x.rows++;if(r.activity==='Sale')x.sales++;if(r.activity==='Harvest'&&r.unit==='kg')x.harvest+=val(r,'quantity');if(r.health)x.health.push(r);}return Object.values(out).sort((a,b)=>(b.revenue-b.cost)-(a.revenue-a.cost));}
  function insights(){const list=[];const rows=workspace.records;const stats=cropStats();const t=totals();const poor=rows.filter(r=>r.health==='Poor'||r.health==='Watch').sort((a,b)=>b.date.localeCompare(a.date));if(poor.length){const last=poor[0];list.push({tone:'amber',icon:'!',title:`Check ${last.crop} health in ${last.field}`,body:`A “${last.health.toLowerCase()}” observation was recorded on ${prettyDate(last.date)}. Inspect the crop and record what you find before choosing a treatment.`,evidence:`${poor.length} watch/poor observation${poor.length===1?'':'s'}`});}
    const losing=stats.filter(c=>c.sales>0&&c.revenue-c.cost<0);for(const c of losing)list.push({tone:'red',icon:'↘',title:`Review ${c.name} costs`,body:`Recorded costs exceed revenue by ${money(c.cost-c.revenue)}. Check whether all sales and costs are entered before changing the crop plan.`,evidence:`${c.rows} records · ${c.sales} sales`});
    const best=stats.find(c=>c.sales>0&&c.revenue>c.cost);if(best)list.push({tone:'green',icon:'↗',title:`${best.name} has the strongest recorded return`,body:`The ledger shows ${money(best.revenue-best.cost)} recorded net for ${best.name}. Compare season, area and market price before expanding.`,evidence:`${best.rows} records · ${best.sales} sales`});
    const withWater=stats.filter(c=>c.water>0);if(withWater.length){const largest=[...withWater].sort((a,b)=>b.water-a.water)[0];list.push({tone:'green',icon:'≈',title:`Log yield alongside ${largest.name} water use`,body:`${fmtNum(largest.water)} L is recorded for ${largest.name}. ${largest.harvest>0?`That is ${fmtNum(largest.water/largest.harvest,1)} L per harvested kg based on available harvest entries.`:'Add harvest weight in kg to calculate water per harvested kg.'}`,evidence:`${largest.rows} crop records`});}
    if(rows.length&&!rows.some(r=>r.activity==='Harvest'&&r.unit==='kg'))list.push({tone:'amber',icon:'+',title:'Add harvest weights',body:'Without harvested kilograms, water efficiency and yield comparisons remain incomplete.',evidence:'Missing harvest data'});
    const missing=rows.filter(r=>r.activity==='Sale'&&r.revenue==null).length;if(missing)list.push({tone:'amber',icon:'?',title:'Complete sale amounts',body:`${missing} sale record${missing===1?' is':'s are'} missing revenue. Profit comparisons may be misleading until these are filled in.`,evidence:`${missing} incomplete sale${missing===1?'':'s'}`});
    if(!rows.length)list.push({tone:'green',icon:'+',title:'Start with your first farm record',body:'Add a planting, irrigation, health check, cost, harvest or sale. Insights will grow from your own history.',evidence:'No records yet'});
    return list;
  }
  function renderSummary(){const t=totals();const net=t.revenue-t.cost;const health=t.health.length;const good=t.health.filter(r=>r.health==='Good').length;const items=[['Recorded net',signedMoney(net),'Revenue − recorded costs','↗',net>=0?'good':'warn'],['Revenue',money(t.revenue),`${workspace.records.filter(r=>r.revenue!=null).length} recorded amounts`,'₹',''],['Water used',`${fmtNum(t.water)} L`,'From irrigation & activity records','≈',''],['Crop health',health?`${Math.round(good/health*100)}% good`:'No checks',health?`${health} health observation${health===1?'':'s'}`:'Add a health observation','✳',health&&good/health<.7?'warn':'good']];$('#summaryGrid').innerHTML=items.map(x=>`<div class="metric-card"><div class="metric-top"><span class="metric-label">${x[0]}</span><span class="metric-icon">${x[3]}</span></div><div class="metric-value">${x[1]}</div><div class="metric-foot ${x[4]}">${x[2]}</div></div>`).join('');}
  function renderChart(){const grouped={};for(const r of workspace.records){const k=monthKey(r.date);if(k)grouped[k]=(grouped[k]||0)+val(r,'revenue')-val(r,'cost');}const keys=Object.keys(grouped).sort().slice(-6);if(!keys.length){$('#profitChart').innerHTML='<div class="empty-state">Add dated costs and sales to see monthly profit.</div>';return;}const max=Math.max(1,...keys.map(k=>Math.abs(grouped[k])));$('#profitChart').innerHTML=keys.map((k,i)=>{const n=grouped[k];return `<div class="bar-group"><div class="bar-track"><div class="bar ${i===keys.length-1?'current':''} ${n<0?'negative':''}" style="height:${Math.max(4,Math.round(Math.abs(n)/max*145))}px" title="${esc(k)}: ${esc(signedMoney(n))}"><span class="bar-value">${n<0?'−':''}${shortMoney(n)}</span></div></div><div class="bar-label">${monthName(k.slice(5))} ’${k.slice(2,4)}</div></div>`;}).join('');}
  function renderAttention(){const list=insights().slice(0,3);$('#attentionList').innerHTML=list.map(x=>`<div class="attention-item"><span class="attention-icon ${x.tone==='amber'?'amber':x.tone==='red'?'red':''}">${x.icon}</span><div><strong>${esc(x.title)}</strong><p>${esc(x.body)}</p></div></div>`).join('');$('#insightCount').textContent=insights().length;}
  function renderRecent(){const rows=[...workspace.records].sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4);$('#recentRecords').innerHTML=rows.length?`<table class="recent-table"><thead><tr><th>Date</th><th>Activity</th><th>Crop / field</th><th>Amount</th></tr></thead><tbody>${rows.map(r=>`<tr><td>${esc(prettyDate(r.date))}</td><td><span class="activity-pill ${esc(r.activity)}">${esc(r.activity)}</span></td><td class="strong">${esc(r.crop)} <span style="font-weight:400;color:#9aa79d">· ${esc(r.field)}</span></td><td>${r.revenue!=null?`+${money(r.revenue)}`:r.cost!=null?`−${money(r.cost)}`:r.water!=null?`${fmtNum(r.water)} L`:'—'}</td></tr>`).join('')}</tbody></table>`:'<div class="empty-state">Your recent farm activity will appear here.</div>';}
  function selectOptions(list,current){return list.map(x=>`<option value="${esc(x)}" ${x===current?'selected':''}>${esc(x||'—')}</option>`).join('');}
  function cell(r,key,type='text',extra=''){const value=r[key]??'';return `<input class="cell-input ${type==='number'?'num':''}" data-id="${esc(r.id)}" data-key="${key}" type="${type}" value="${esc(value)}" ${extra} aria-label="${esc(key)} for ${esc(r.crop)}">`;}
  function renderSheet(){const query=$('#sheetSearch').value.trim().toLowerCase(),filter=$('#sheetFilter').value;const rows=[...workspace.records].sort((a,b)=>b.date.localeCompare(a.date)).filter(r=>(filter==='all'||r.activity===filter)&&(!query||[r.date,r.field,r.crop,r.activity,r.notes].some(v=>String(v||'').toLowerCase().includes(query))));$('#recordCount').textContent=workspace.records.length;$('#sheetFooterText').textContent=`${rows.length} of ${workspace.records.length} records shown`;$('#sheetBody').innerHTML=rows.length?rows.map((r,i)=>`<tr><td>${i+1}</td><td>${cell(r,'date','date')}</td><td><select class="cell-select" data-id="${esc(r.id)}" data-key="field">${selectOptions([...new Set([...workspace.fields.map(f=>f.name),r.field])],r.field)}</select></td><td>${cell(r,'crop')}</td><td><select class="cell-select" data-id="${esc(r.id)}" data-key="activity">${selectOptions(ACTIVITIES,r.activity)}</select></td><td>${cell(r,'quantity','number','min="0" step="any"')}</td><td><select class="cell-select" data-id="${esc(r.id)}" data-key="unit">${selectOptions(UNITS,r.unit)}</select></td><td>${cell(r,'water','number','min="0" step="any"')}</td><td>${cell(r,'cost','number','min="0" step="any"')}</td><td>${cell(r,'revenue','number','min="0" step="any"')}</td><td><select class="cell-select" data-id="${esc(r.id)}" data-key="health">${selectOptions(HEALTH,r.health)}</select></td><td>${cell(r,'notes')}</td><td><button class="row-menu" data-delete="${esc(r.id)}" title="Delete row" aria-label="Delete row">×</button></td></tr>`).join(''):'<tr><td colspan="13"><div class="empty-state">No matching records. Add a row or change the filters.</div></td></tr>';}
  function renderMatrix(){const stats=cropStats();const keys=[...new Set(workspace.records.map(r=>monthKey(r.date)).filter(Boolean))].sort().slice(-5);if(!stats.length||!keys.length){$('#monthMatrix').innerHTML='<div class="empty-state">Add dated crop records to compare months.</div>';return;}const cells={};for(const r of workspace.records){const k=`${r.crop}|${monthKey(r.date)}`;cells[k]??={profit:0,count:0};cells[k].profit+=val(r,'revenue')-val(r,'cost');cells[k].count++;}$('#monthMatrix').innerHTML=`<div class="matrix-wrap"><table class="matrix"><thead><tr><th>Crop</th>${keys.map(k=>`<th>${monthName(k.slice(5))} ’${k.slice(2,4)}</th>`).join('')}</tr></thead><tbody>${stats.map(c=>`<tr><td>${esc(c.name)}</td>${keys.map(k=>{const v=cells[`${c.name}|${k}`];return v?`<td class="${v.profit>=0?'positive':'negative'}" title="${v.count} records">${signedMoney(v.profit)}</td>`:'<td class="no-data">—</td>'}).join('')}</tr>`).join('')}</tbody></table></div>`;}
  function renderRanking(){const stats=cropStats();if(!stats.length){$('#cropRanking').innerHTML='<div class="empty-state">Add crop costs and sales to compare returns.</div>';return;}const max=Math.max(1,...stats.map(c=>Math.abs(c.revenue-c.cost)));$('#cropRanking').innerHTML=stats.map(c=>{const n=c.revenue-c.cost;return `<div class="ranking-item"><strong>${esc(c.name)}</strong><div class="rank-track"><div class="rank-bar ${n<0?'negative':''}" style="width:${Math.max(3,Math.abs(n)/max*100)}%"></div></div><span style="color:${n<0?'#c97967':''}">${signedMoney(n)}</span></div>`}).join('')+'<p style="font-size:10px;color:#a0aca1;margin-top:20px">Includes costs from crops that may not have been sold yet.</p>';}
  function renderRecommendations(){const list=insights();$('#insightBasis').textContent=`Based on ${workspace.records.length} records`;$('#recommendations').innerHTML=list.map(x=>`<article class="recommendation-card"><div class="rec-top"><span class="rec-icon">${x.icon}</span><span class="rec-tag">${x.tone==='red'?'Review':x.tone==='amber'?'Check':'Observed'}</span></div><h3>${esc(x.title)}</h3><p>${esc(x.body)}</p><div class="rec-evidence">↳ ${esc(x.evidence)}</div></article>`).join('');}
  function renderFields(){const list=$('#fieldList');list.innerHTML=workspace.fields.length?workspace.fields.map(f=>`<div class="field-row"><div><strong>${esc(f.name)}</strong><small>${f.area!=null?`${fmtNum(f.area,2)} acres`:'Area not recorded'}</small></div><button data-remove-field="${esc(f.name)}" title="Remove field" aria-label="Remove ${esc(f.name)}">×</button></div>`).join(''):'<div class="empty-state">Add your first field below.</div>';const options=workspace.fields.map(f=>`<option value="${esc(f.name)}">${esc(f.name)}</option>`).join('');$('#formField').innerHTML=options;const crops=[...new Set(workspace.records.map(r=>r.crop).filter(Boolean))].sort();$('#cropOptions').innerHTML=crops.map(c=>`<option value="${esc(c)}"></option>`).join('');$('#researchCrop').innerHTML='<option value="">All crops</option>'+crops.map(c=>`<option value="${esc(c)}">${esc(c)}</option>`).join('');}
  function render(){const isSample=!!workspace.sample;$('#sampleBanner').style.display=isSample?'flex':'none';$('#settingsClearSample').disabled=!isSample;renderSummary();renderChart();renderAttention();renderRecent();renderSheet();renderMatrix();renderRanking();renderRecommendations();renderFields();}
  function openRecord(){if(!workspace.fields.length){showView('settings');notify('Add a field first, then enter a record.');$('#newFieldName').focus();return;}editId=null;$('#dialogTitle').textContent='Add a record';$('#recordForm').reset();$('#recordForm').elements.date.value=new Date().toLocaleDateString('en-CA');renderFields();$('#recordDialog').showModal();}
  function commitCell(target){const id=target.dataset.id,key=target.dataset.key;if(!id||!key)return;const r=workspace.records.find(r=>r.id===id);if(!r)return;let value=target.value;if(['quantity','water','cost','revenue'].includes(key)){value=number(value);if(value!=null&&value<0){notify('Enter a positive amount.');target.value=r[key]??'';return;}}else if(key==='crop'||key==='notes')value=value.trim();if(key==='date'&&!/^\d{4}-\d{2}-\d{2}$/.test(value)){notify('Enter a valid date.');target.value=r.date;return;}if(key==='crop'&&!value){target.value=r.crop;return;}r[key]=value;save();renderSummary();renderChart();renderAttention();renderRecent();renderMatrix();renderRanking();renderRecommendations();}
  function confirm(title,message,label,callback){confirmCallback=callback;$('#confirmTitle').textContent=title;$('#confirmMessage').textContent=message;$('#confirmAction').textContent=label;$('#confirmDialog').showModal();}
  function clearSample(){confirm('Start with your farm?','The illustrative records and fields will be removed. Export them first if you want a copy.','Clear sample',()=>{workspace={version:1,sample:false,fields:[],records:[]};save();render();showView('sheet');notify('Sample cleared. Add your first field, then a record.');});}
  const CSV_FIELDS=['date','field','crop','activity','quantity','unit','water','cost','revenue','health','notes'];
  function csvEscape(v){const s=String(v??'');return /[",\r\n]/.test(s)?`"${s.replace(/"/g,'""')}"`:s;}
  function downloadFile(content,filename,mime){if(window.BrahmaNative?.saveFile){window.BrahmaNative.saveFile(content,filename,mime);notify('Choose where to save the backup.');return;}const message={action:'saveFile',content,filename,mime};if(window.webkit?.messageHandlers?.brahma){window.webkit.messageHandlers.brahma.postMessage(message);notify('Choose where to save the backup.');return;}if(window.chrome?.webview?.postMessage){window.chrome.webview.postMessage(message);notify('Choose where to save the backup.');return;}const blob=new Blob([content],{type:`${mime};charset=utf-8`});const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=filename;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Backup downloaded.');}
  function exportCSV(){const content=[CSV_FIELDS.join(','),...workspace.records.map(r=>CSV_FIELDS.map(k=>csvEscape(r[k])).join(','))].join('\r\n');downloadFile('\ufeff'+content,`brahmafarm-records-${new Date().toLocaleDateString('en-CA')}.csv`,'text/csv');}
  function exportBackup(){const payload={format:'brahmafarm-backup',version:1,exportedAt:new Date().toISOString(),fields:workspace.fields,records:workspace.records};downloadFile(JSON.stringify(payload,null,2),`brahmafarm-full-backup-${new Date().toLocaleDateString('en-CA')}.json`,'application/json');}
  async function importBackup(file){
    if(!file)return;
    try{
      const data=JSON.parse(await file.text());
      if(data.format!=='brahmafarm-backup'||data.version!==1||!Array.isArray(data.fields)||!Array.isArray(data.records))throw new Error('This is not a BrahmaFarm backup file.');
      const fields=data.fields.map(f=>({name:String(f.name||'').trim().slice(0,40),area:number(f.area)})).filter(f=>f.name);
      const records=data.records.map(raw=>{const r={id:String(raw.id||uid())};for(const k of CSV_FIELDS)r[k]=['quantity','water','cost','revenue'].includes(k)?number(raw[k]):String(raw[k]??'').trim();return r;});
      if(records.some(r=>!/^\d{4}-\d{2}-\d{2}$/.test(r.date)||!r.field||!r.crop||!ACTIVITIES.includes(r.activity)||['quantity','water','cost','revenue'].some(k=>r[k]!=null&&r[k]<0)))throw new Error('The backup contains invalid farm records.');
      const beforeRecords=workspace.records.length,beforeFields=workspace.fields.length;
      confirm('Restore this backup?',`This will replace ${beforeRecords} local record${beforeRecords===1?'':'s'} and ${beforeFields} field${beforeFields===1?'':'s'} with ${records.length} record${records.length===1?'':'s'} and ${fields.length} field${fields.length===1?'':'s'} from the file.`,'Restore backup',()=>{workspace={version:1,sample:false,fields,records};save();render();showView('overview');notify('Complete backup restored.');});
    }catch(e){notify(e.message||'Could not read backup.');}finally{$('#jsonFile').value='';}
  }
  function parseCSV(text){const rows=[];let row=[],field='',quoted=false;for(let i=0;i<text.length;i++){const c=text[i];if(quoted){if(c==='"'&&text[i+1]==='"'){field+='"';i++;}else if(c==='"')quoted=false;else field+=c;}else if(c==='"')quoted=true;else if(c===','){row.push(field);field='';}else if(c==='\n'||c==='\r'){if(c==='\r'&&text[i+1]==='\n')i++;row.push(field);if(row.some(x=>x!==''))rows.push(row);row=[];field='';}else field+=c;}row.push(field);if(row.some(x=>x!==''))rows.push(row);return rows;}
  async function importCSV(file){if(!file)return;try{const content=(await file.text()).replace(/^\ufeff/,'');const rows=parseCSV(content);const header=rows.shift()?.map(x=>x.trim().toLowerCase());if(!header||!['date','field','crop','activity'].every(k=>header.includes(k)))throw new Error('CSV needs date, field, crop and activity columns. Export a template first.');const imported=[];for(const cells of rows){const raw=Object.fromEntries(header.map((k,i)=>[k,cells[i]??'']));if(!/^\d{4}-\d{2}-\d{2}$/.test(raw.date)||!raw.field||!raw.crop||!ACTIVITIES.includes(raw.activity))continue;const r={id:uid()};for(const k of CSV_FIELDS)r[k]=['quantity','water','cost','revenue'].includes(k)?number(raw[k]):String(raw[k]??'').trim();if(['quantity','water','cost','revenue'].some(k=>r[k]!=null&&r[k]<0))continue;if(!HEALTH.includes(r.health))r.health='';imported.push(r);}if(!imported.length)throw new Error('No valid records found. Check dates and activity names.');const fingerprint=r=>CSV_FIELDS.map(k=>String(r[k]??'')).join('\u001f');const seen=new Set((workspace.sample?[]:workspace.records).map(fingerprint));const fresh=imported.filter(r=>{const key=fingerprint(r);if(seen.has(key))return false;seen.add(key);return true;});if(!fresh.length){notify('These CSV records are already in the ledger.');return;}const names=new Set(workspace.fields.map(f=>f.name));for(const r of fresh)if(!names.has(r.field)){workspace.fields.push({name:r.field,area:null});names.add(r.field);}if(workspace.sample)workspace.records=[];workspace.records.push(...fresh);workspace.sample=false;save();render();showView('sheet');notify(`${fresh.length} record${fresh.length===1?'':'s'} imported.`);}catch(e){notify(e.message||'Could not import CSV.');}finally{$('#csvFile').value='';}}
  function makeResearch(){const question=$('#researchQuestion').value.trim();if(!question){notify('Enter a farm question first.');return;}const crop=$('#researchCrop').value;const records=workspace.records.filter(r=>!crop||r.crop===crop);const t=totals(records);const s=crop?cropStats().find(x=>x.name===crop):null;const health=records.filter(r=>r.health==='Watch'||r.health==='Poor').sort((a,b)=>b.date.localeCompare(a.date));const lines=[];lines.push(`${records.length} relevant record${records.length===1?' is':'s are'} available${crop?` for ${crop}`:''}.`);if(records.length){lines.push(`Recorded revenue ${money(t.revenue)}, cost ${money(t.cost)}, net ${signedMoney(t.revenue-t.cost)}.`);if(t.water)lines.push(`Water logged: ${fmtNum(t.water)} L${t.harvest?` over ${fmtNum(t.harvest)} harvested kg (${fmtNum(t.water/t.harvest,1)} L/kg, based on entered harvests)`:'; harvest weight is needed for L/kg'}.`);if(health.length)lines.push(`Latest watch/poor health note: ${health[0].crop} in ${health[0].field} on ${prettyDate(health[0].date)}${health[0].notes?` — ${health[0].notes}`:''}.`);}const gaps=[];if(!records.some(r=>r.activity==='Harvest'&&r.unit==='kg'))gaps.push('Harvest weight in kilograms is missing; add it for yield and water comparisons.');if(!records.some(r=>r.activity==='Sale'))gaps.push('No sale has been recorded; profit cannot establish a completed crop return.');if(!records.some(r=>r.health))gaps.push('There are no crop health observations to compare.');if(!records.length)gaps.push('Add your own records before using this brief for a farm decision.');if(s?.sales&&s.revenue-s.cost>0)gaps.push('Historical profit is only one input; check current prices, weather and input costs.');const topic=`${crop?crop+' ':''}${question} agriculture`;const q=encodeURIComponent(topic);const sourceLinks=[['FAO',`https://www.google.com/search?q=${encodeURIComponent('site:fao.org '+topic)}`],['ICAR',`https://www.google.com/search?q=${encodeURIComponent('site:icar.gov.in '+topic)}`],['Google Scholar',`https://scholar.google.com/scholar?q=${q}`]];$('#researchResult').classList.remove('empty-research');$('#researchResult').innerHTML=`<div class="eyebrow">RESEARCH BRIEF</div><h3>${esc(question)}</h3><div class="brief-section"><h4>What your records say</h4><ul>${lines.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="brief-section"><h4>What to verify next</h4><ul>${(gaps.length?gaps:['Compare this result with local weather, soil condition and market prices before acting.']).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div><div class="brief-section"><h4>Search trusted sources</h4><div class="source-links">${sourceLinks.map(([name,url])=>`<a href="${url}" target="_blank" rel="noopener noreferrer">${name} ↗</a>`).join('')}</div></div><div class="brief-notice">This is a structured research brief from your data, not an AI generated agronomy diagnosis. Source links open external searches for you to review.</div>`;}
  function bind(){document.addEventListener('click',e=>{const view=e.target.closest('[data-view]');if(view){showView(view.dataset.view);return;}if(e.target.closest('[data-action="add"]'))openRecord();const del=e.target.closest('[data-delete]');if(del){const r=workspace.records.find(x=>x.id===del.dataset.delete);if(r)confirm('Delete this record?',`${prettyDate(r.date)} · ${r.crop} · ${r.activity}. This removes the row from your local ledger.`,'Delete row',()=>{workspace.records=workspace.records.filter(x=>x.id!==r.id);workspace.sample=false;save();render();notify('Record deleted.');});}const rem=e.target.closest('[data-remove-field]');if(rem){const name=rem.dataset.removeField;if(workspace.records.some(r=>r.field===name)){notify('This field has records. Rename those rows before removing it.');return;}workspace.fields=workspace.fields.filter(f=>f.name!==name);save();render();notify('Field removed.');}const prompt=e.target.closest('[data-prompt]');if(prompt){$('#researchQuestion').value=prompt.dataset.prompt;$('#researchQuestion').focus();}});
    $('#recordForm').addEventListener('submit',e=>{e.preventDefault();const form=new FormData(e.target);const r={id:uid()};for(const k of CSV_FIELDS)r[k]=['quantity','water','cost','revenue'].includes(k)?number(form.get(k)):String(form.get(k)||'').trim();if(!r.field){notify('Add a field in Farm settings first.');showView('settings');$('#recordDialog').close();return;}workspace.records.push(r);save();$('#recordDialog').close();render();notify('Record saved.');});
    $('#closeDialog').onclick=$('#cancelDialog').onclick=()=>$('#recordDialog').close();$('#closeConfirm').onclick=$('#cancelConfirm').onclick=()=>$('#confirmDialog').close();$('#confirmDialog').addEventListener('close',()=>{if($('#confirmDialog').returnValue==='confirm'&&confirmCallback)confirmCallback();confirmCallback=null;});$('#confirmAction').value='confirm';
    $('#sheetBody').addEventListener('change',e=>{if(e.target.matches('[data-id][data-key]'))commitCell(e.target);});$('#sheetBody').addEventListener('focusout',e=>{if(e.target.matches('input[data-id][data-key]'))commitCell(e.target);});$('#sheetSearch').addEventListener('input',renderSheet);$('#sheetFilter').addEventListener('change',renderSheet);
    $('#importButton').onclick=$('#settingsImport').onclick=()=>$('#csvFile').click();$('#csvFile').addEventListener('change',e=>importCSV(e.target.files[0]));$('#exportButton').onclick=$('#settingsExport').onclick=exportCSV;$('#backupExport').onclick=exportBackup;$('#backupImport').onclick=()=>$('#jsonFile').click();$('#jsonFile').addEventListener('change',e=>importBackup(e.target.files[0]));
    $('#clearSampleButton').onclick=$('#settingsClearSample').onclick=clearSample;$('#deleteAllButton').onclick=()=>confirm('Delete every local record?','All records on this device will be erased. Export a CSV backup first if you may need them later.','Delete records',()=>{workspace.records=[];workspace.sample=false;save();render();notify('All local records deleted.');});
    $('#fieldForm').addEventListener('submit',e=>{e.preventDefault();const name=titleCase($('#newFieldName').value);const area=number($('#newFieldArea').value);if(!name)return;if(workspace.fields.some(f=>f.name.toLowerCase()===name.toLowerCase())){notify('That field already exists.');return;}workspace.fields.push({name,area});save();e.target.reset();render();notify('Field added.');});$('#researchButton').onclick=makeResearch;$('#helpButton').onclick=()=>{showView('research');$('#researchQuestion').focus();};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&!$('#recordDialog').open){e.preventDefault();openRecord();}});
  }
  workspace=load();$('#todayLabel').textContent=new Date().toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short',year:'numeric'});bind();render();showView(['overview','sheet','insights','research','settings'].includes(location.hash.slice(1))?location.hash.slice(1):'overview');if('serviceWorker' in navigator&&location.protocol.startsWith('http'))navigator.serviceWorker.register('./service-worker.js').catch(()=>{});
})();
